 60	  extern DSI_HandleTypeDef hdsi_eval;
 61	  extern int32_t DSI_IO_ReadCmd(uint32_t Reg, uint8_t *pData, uint32_t Size);
 62	
 63	  /* Bat BTA flow control tren DSI Host */
 64	  HAL_DSI_ConfigFlowControl(&hdsi_eval, DSI_FLOW_CONTROL_BTA);
 65	
 66	  /* 0x11: Sleep Out */
 67	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00);
 68	  HAL_Delay(120);
 69	  /* 0x51: WRDISBV - dat do sang toi da (0xFF) */
 70	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, 0xFF);
 71	  /* 0x53: WRCTRLD - bat BCTRL (0x2C: BCTRL=1, DD=1, BL=1) */
 72	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C);
 73	  /* 0x29: Display On */
 74	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00);
 75	  HAL_Delay(50);
 76	
 77	  /* Doc cac thanh ghi trang thai DCS cua panel va luu ma tra ve */
 78	  g_panel_read_ret[0] = DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_status[0], 1); g_panel_dcs[0] = g_panel_status[0]; /* ID1 */
 79	  g_panel_read_ret[1] = DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_status[1], 1); g_panel_dcs[1] = g_panel_status[1]; /* Power Mode */
 80	  g_panel_read_ret[2] = DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_status[2], 1); g_panel_dcs[2] = g_panel_status[2]; /* MADCTL */
 81	  g_panel_read_ret[3] = DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_status[3], 1); g_panel_dcs[3] = g_panel_status[3]; /* COLMOD */
 82	  g_panel_read_ret[4] = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_status[4], 1); g_panel_dcs[4] = g_panel_status[4]; /* Brightness */
 83	  g_panel_read_ret[5] = DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_status[5], 1); g_panel_dcs[5] = g_panel_status[5]; /* CTRL Display */
 84	  g_panel_read_ret[6] = DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_status[6], 1); g_panel_dcs[6] = g_panel_status[6]; /* Self-Diagnostic */
 85	  g_panel_read_ret[7] = DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_status[7], 1); g_panel_dcs[7] = g_panel_status[7]; /* Image Mode */
