 99	  BSP_LCD_SetTextColor(LCD_COLOR_DARKBLUE);
100	  BSP_LCD_SetFont(&Font20);
101	
102	  /* Dong 1: EIDE v3 — IDE nhung co tac tu dong tac gia */
103	  BSP_LCD_DisplayStringAt(0, 290, (uint8_t *)"EIDE v3 - IDE nhung co tac tu dong tac gia", CENTER_MODE);
104	
105	  BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
106	  BSP_LCD_SetFont(&Font16);
107	
108	  /* Dong 2: Hoc vien: Vu Tri Cong */
109	  BSP_LCD_DisplayStringAt(0, 330, (uint8_t *)"Hoc vien: Vu Tri Cong", CENTER_MODE);
110	
111	  /* Dong 3: Giang vien huong dan: TS. Nguyen Trung Hieu */
112	  BSP_LCD_DisplayStringAt(0, 360, (uint8_t *)"Giang vien huong dan: TS. Nguyen Trung Hieu", CENTER_MODE);
113	
114	  BSP_LCD_SetTextColor(LCD_COLOR_RED);
115	  /* Dong 4: Hoc vien Cong nghe Buu chinh Vien thong */
116	  BSP_LCD_DisplayStringAt(0, 400, (uint8_t *)"Hoc vien Cong nghe Buu chinh Vien thong", CENTER_MODE);
117	
118	  /* Dong 5: Trang thai DCS panel do o Command Mode va Video Mode */
119	  static const char hex_chars[] = "0123456789ABCDEF";
120	  char cmd_buf[48] = "CMD: ID=00 PWR=00 BRT=00 CTL=00";

121	  cmd_buf[8]  = hex_chars[(g_panel_cmd_status[0] >> 4) & 0x0F];
122	  cmd_buf[9]  = hex_chars[g_panel_cmd_status[0] & 0x0F];
123	  cmd_buf[15] = hex_chars[(g_panel_cmd_status[1] >> 4) & 0x0F];
124	  cmd_buf[16] = hex_chars[g_panel_cmd_status[1] & 0x0F];
125	  cmd_buf[22] = hex_chars[(g_panel_cmd_status[4] >> 4) & 0x0F];
126	  cmd_buf[23] = hex_chars[g_panel_cmd_status[4] & 0x0F];
127	  cmd_buf[29] = hex_chars[(g_panel_cmd_status[5] >> 4) & 0x0F];
128	  cmd_buf[30] = hex_chars[g_panel_cmd_status[5] & 0x0F];
129	
130	  char vid_buf[48] = "VID: ID=00 PWR=00 BRT=00 CTL=00";
131	  vid_buf[8]  = hex_chars[(g_panel_dcs[0] >> 4) & 0x0F];
132	  vid_buf[9]  = hex_chars[g_panel_dcs[0] & 0x0F];
133	  vid_buf[15] = hex_chars[(g_panel_dcs[1] >> 4) & 0x0F];
134	  vid_buf[16] = hex_chars[g_panel_dcs[1] & 0x0F];
135	  vid_buf[22] = hex_chars[(g_panel_dcs[4] >> 4) & 0x0F];
136	  vid_buf[23] = hex_chars[g_panel_dcs[4] & 0x0F];
137	  vid_buf[29] = hex_chars[(g_panel_dcs[5] >> 4) & 0x0F];
138	  vid_buf[30] = hex_chars[g_panel_dcs[5] & 0x0F];
139	
140	  BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
141	  BSP_LCD_SetFont(&Font12);
142	  BSP_LCD_DisplayStringAt(0, 435, (uint8_t *)cmd_buf, CENTER_MODE);
143	  BSP_LCD_DisplayStringAt(0, 452, (uint8_t *)vid_buf, CENTER_MODE);
144	
145	  while (1)
146	  {
147	    HAL_Delay(1000);
148	  }
149	}
