151	static void DrawLogo(uint32_t x0, uint32_t y0)
152	{
153	  for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
154	  {
155	    for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
156	    {
157	      uint32_t pixel = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
158	      uint8_t a = (pixel >> 24) & 0xFF;
159	      if (a > 0)
160	      {
161	        if (a == 255)
162	        {
163	          BSP_LCD_DrawPixel(x0 + x, y0 + y, pixel);
164	        }
165	        else
166	        {
167	          uint32_t r = (pixel >> 16) & 0xFF;
168	          uint32_t g = (pixel >> 8) & 0xFF;
169	          uint32_t b = pixel & 0xFF;
170	          r = (r * a + 255 * (255 - a)) / 255;
171	          g = (g * a + 255 * (255 - a)) / 255;
172	          b = (b * a + 255 * (255 - a)) / 255;
173	          BSP_LCD_DrawPixel(x0 + x, y0 + y, 0xFF000000UL | (r << 16) | (g << 8) | b);
174	        }
175	      }
176	    }
177	  }
178	}
